+import { resolve } from "@std/path";
+import { ConfigParseError } from "./errors.ts";
+import type { ConfigOptions, ConfigValues } from "./types.ts";
+
+export interface LoadedConfig {
+  path?: string;
+  values: ConfigValues;
+}
+
+export async function loadConfig(options: ConfigOptions): Promise<LoadedConfig> {
+  const paths = options.searchPaths ?? [Deno.cwd()];
+  const formats = options.formats ?? [".json", ".rc"];
+  const matches: Array<{ path: string; format: string }> = [];
+
+  for (const searchPath of paths) {
+    for (const format of formats) {
+      const filename = format === ".rc" ? `.${options.name}rc` : `${options.name}${format}`;
+      const path = resolve(searchPath, filename);
+      try {
+        await Deno.stat(path);
+        matches.push({ path, format });
+        if (!options.mergeConfigs) break;
+      } catch (error) {
+        if (!(error instanceof Deno.errors.NotFound)) throw error;
+      }
+    }
+    if (matches.length && !options.mergeConfigs) break;
+  }
+
+  const values: ConfigValues = {};
+  for (const match of matches) {
+    const content = await Deno.readTextFile(match.path);
+    let parsed: Record<string, unknown>;
+    try {
+      parsed = options.parser
+        ? options.parser(content)
+        : match.format === ".json" ? JSON.parse(content) : parseRc(content);
+      if (!isPlainObject(parsed)) throw new TypeError("Configuration must be an object");
+    } catch (error) {
+      throw new ConfigParseError(match.path, error);
+    }
+    // Earlier paths take precedence when files are merged.
+    for (const [key, value] of Object.entries(flatten(parsed))) {
+      if (!(key in values)) values[key] = value;
+    }
+  }
+  return { path: matches[0]?.path, values };
+}
+
+function parseRc(content: string): Record<string, unknown> {
+  const result: ConfigValues = {};
+  for (const line of content.split(/\\r?\
/)) {
+    const trimmed = line.trim();
+    if (!trimmed || trimmed.startsWith("#")) continue;
+    const match = /^([^=]+)=(.*)$/.exec(trimmed);
+    if (!match) throw new TypeError("Invalid RC entry");
+    const key = match[1].trim();
+    let value = match[2].trim();
+    if (value.startsWith('"') && value.endsWith('"') && value.length >= 2) {
+      value = value.slice(1, -1);
+    } else if (value === "true") {
+      result[toCamelCase(key)] = true;
+      continue;
+    } else if (value === "false") {
+      result[toCamelCase(key)] = false;
+      continue;
+    } else if (/^-?(?:\\d+\\.?\\d*|\\.\\d+)$/.test(value)) {
+      result[toCamelCase(key)] = Number(value);
+      continue;
+    }
+    result[toCamelCase(key)] = value;
+  }
+  return result;
+}
+
+function flatten(value: Record<string, unknown>, prefix = ""): ConfigValues {
+  const result: ConfigValues = {};
+  for (const [rawKey, item] of Object.entries(value)) {
+    const key = prefix ? `${prefix}.${toCamelCase(rawKey)}` : toCamelCase(rawKey);
+    if (isPlainObject(item)) Object.assign(result, flatten(item, key));
+    else result[key] = item;
+  }
+  return result;
+}
+
+function isPlainObject(value: unknown): value is Record<string, unknown> {
+  return !!value && typeof value === "object" && !Array.isArray(value) &&
+    (Object.getPrototypeOf(value) === Object.prototype || Object.getPrototypeOf(value) === null);
+}
+
+export function toCamelCase(value: string): string {
+  return value.replace(/-([a-zA-Z0-9])/g, (_, char) => char.toUpperCase());
+}
